import sys

def main():
    input = sys.stdin.buffer.readline
    line = input()
    if not line:
        return

    n = int(line)
    answer = 0

    for _ in range(n):
        a, b = map(int, input().split())
        if not (a == 0 and b == 1):
            answer += 1

    print(answer)

if __name__ == "__main__":
    main()
